-- market_data_fixed.sql — cleaned export for Trade Ledger
-- See database/DATA_ISSUES.md for what was wrong and how it was fixed.

USE [MarketData];
GO

IF OBJECT_ID('dbo.DailyPrices', 'U') IS NOT NULL DROP TABLE dbo.DailyPrices;
IF OBJECT_ID('dbo.Instruments', 'U') IS NOT NULL DROP TABLE dbo.Instruments;
GO

CREATE TABLE dbo.Instruments (
    InstrumentId INT IDENTITY(1,1) NOT NULL,
    Code NVARCHAR(20) NOT NULL,
    Name NVARCHAR(200) NULL,
    AssetClass NVARCHAR(20) NULL,
    Exchange NVARCHAR(10) NULL,
    Currency CHAR(3) NULL,
    QuoteUnit NVARCHAR(20) NULL,
    ContractSize DECIMAL(18, 4) NULL,
    CONSTRAINT PK_Instruments PRIMARY KEY (InstrumentId),
    CONSTRAINT UQ_Instruments_Code UNIQUE (Code)
);
GO

CREATE TABLE dbo.DailyPrices (
    InstrumentId INT NOT NULL,
    PriceDate DATE NOT NULL,
    ClosePrice DECIMAL(18, 6) NOT NULL,
    AccruedPer100 DECIMAL(18, 6) NULL,
    Source NVARCHAR(50) NULL,
    CONSTRAINT PK_DailyPrices PRIMARY KEY (InstrumentId, PriceDate),
    CONSTRAINT FK_DailyPrices_Instruments FOREIGN KEY (InstrumentId)
        REFERENCES dbo.Instruments (InstrumentId)
);
GO

